public async Task<IActionResult> StoreCsvFile([FromForm] IFormFile file)
{
    // Validate file format
    if (file != null && file.ContentType.Contains("text/csv"))
    {
        try
        {
            // Read the CSV file content
            using (var stream = file.OpenReadStream())
            {
                using (var reader = new StreamReader(stream))
                {
                    // Parse the CSV file
                    var parser = new CsvParser();
                    var records = parser.Parse(reader);

                    // Convert records to JSON
                    var jsonString = JsonSerializer.Serialize(records);

                    // Save the JSON record to Azure Cosmos DB
                    await _cosmosDbService.UploadJsonDataAsync(jsonString);
                }
            }

            return Ok("CSV file stored successfully.");
        }
        catch (Exception ex)
        {
            return StatusCode(500, $"Error storing CSV file: {ex.Message}");
        }
    }
    else
    {
        return BadRequest("Invalid file type. Only CSV files are allowed.");
    }
}

